#!/usr/bin/env python3
"""Stateful mock of a customer's API, generated by Heimdall from an OpenAPI file.

Python standard library only, so the image needs nothing but python3 and the
task never reaches the real system. mock.json (MOCK_PATH, default
/srv/mock.json, written by `bifrost-bench mock openapi`) lists the API's
operations; each one is served twice: as the HTTP route the spec names and
as an MCP tool of the same name.

State: the seed (SEED_PATH, default /seed/state.json, copied in by the
task's files:) is a JSON object of collections, {"orders": [{"id": ...}]}.
Every change is saved to STATE_PATH (default /state/state.json), which the
bench exports after the agent exits for checks.yaml state checks.

Operation kinds (mock.json "kind"):
  list    GET /orders            the collection, filtered by query fields
  get     GET /orders/{id}       one item, 404 when missing
  create  POST /orders           adds the body (an id is made when missing)
  update  PUT|PATCH /orders/{id} merges the body into the item
  delete  DELETE /orders/{id}    removes the item
  action  anything else          recorded in the "_actions" collection and
                                 answered {"ok": true} (or by a fixture)
A nested path such as /customers/{customer_id}/orders filters and stamps
the parent field (customer_id) on the child collection.

Record and replay: every request is appended to RECORD_PATH (default
/state/calls.jsonl), exported with the state. mock.json "fixtures" answer
matching requests first, in order: {"method", "path" (a template or the exact
path), "body" (a subset the request body must hold), "status", "response",
"times" (default unlimited)}. `bifrost-bench mock fixtures` writes fixtures
from a run's recorded calls. MOCK_MODE=replay answers only from fixtures:
an unmatched request gets 501.

Protocols, both on one port (PORT, default 8000): the API's own routes,
MCP over streamable HTTP at MCP_PATH (default /mcp), GET /healthz.

Commands:
  python3 server.py           serve
  python3 server.py ready     exit 0 when the local server answers /healthz
"""

import json
import os
import re
import sys
import tempfile
import threading
import urllib.parse
import urllib.request
import uuid
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

MOCK_PATH = os.environ.get("MOCK_PATH", "/srv/mock.json")
SEED_PATH = os.environ.get("SEED_PATH", "/seed/state.json")
STATE_PATH = os.environ.get("STATE_PATH", "/state/state.json")
RECORD_PATH = os.environ.get("RECORD_PATH", "/state/calls.jsonl")
MODE = os.environ.get("MOCK_MODE", "stateful")
PORT = int(os.environ.get("PORT", "8000"))
MCP_PATH = os.environ.get("MCP_PATH", "/mcp")
PROTOCOL_VERSIONS = ["2025-06-18", "2025-03-26", "2024-11-05"]
MAX_BODY = 1 << 20


def template_re(path):
    parts = re.split(r"(\{[^}/]+\})", path)
    out = ""
    for p in parts:
        if p.startswith("{") and p.endswith("}"):
            out += "(?P<%s>[^/]+)" % re.sub(r"\W", "_", p[1:-1])
        else:
            out += re.escape(p)
    return re.compile("^" + out + "/?$")


def subset(want, got):
    if isinstance(want, dict):
        return isinstance(got, dict) and all(k in got and subset(v, got[k]) for k, v in want.items())
    return want == got


class Mock:
    def __init__(self):
        with open(MOCK_PATH, encoding="utf-8") as f:
            self.spec = json.load(f)
        self.name = self.spec.get("name") or "api-mock"
        self.ops = self.spec.get("operations") or []
        for op in self.ops:
            op["_re"] = template_re(op["path"])
        self.fixtures = [dict(x, _used=0) for x in self.spec.get("fixtures") or []]
        for fx in self.fixtures:
            fx["_re"] = template_re(fx.get("path") or "/")
        self.db = {}
        if os.path.exists(SEED_PATH):
            with open(SEED_PATH, encoding="utf-8") as f:
                self.db = json.load(f)
        if not isinstance(self.db, dict):
            raise SystemExit("seed must be a JSON object of collections")
        for op in self.ops:
            if op.get("collection"):
                self.db.setdefault(op["collection"], [])
        self.db.setdefault("_actions", [])
        self.lock = threading.Lock()
        self.seq = 0
        self.save()

    def save(self):
        folder = os.path.dirname(STATE_PATH) or "."
        os.makedirs(folder, exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=folder, prefix=".state-")
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(self.db, f, indent=2, sort_keys=True)
            f.write("\n")
        os.chmod(tmp, 0o644)
        os.replace(tmp, STATE_PATH)

    def record(self, row):
        folder = os.path.dirname(RECORD_PATH) or "."
        os.makedirs(folder, exist_ok=True)
        with open(RECORD_PATH, "a", encoding="utf-8") as f:
            f.write(json.dumps(row, sort_keys=True) + "\n")

    def route(self, method, path):
        for op in self.ops:
            if op["method"] == method:
                m = op["_re"].match(path)
                if m:
                    return op, m.groupdict()
        return None, None

    def fixture(self, method, path, body):
        for fx in self.fixtures:
            if (fx.get("method") or "GET").upper() != method:
                continue
            if not (fx.get("path") == path or fx["_re"].match(path)):
                continue
            if "body" in fx and not subset(fx["body"], body):
                continue
            times = fx.get("times")
            if times is not None and fx["_used"] >= times:
                continue
            fx["_used"] += 1
            return fx.get("status", 200), fx.get("response")
        return None

    def handle(self, method, path, query, body, via):
        """Returns (status, response) and records the request."""
        with self.lock:
            self.seq += 1
            op, params = self.route(method, path)
            hit = self.fixture(method, path, body)
            if hit is not None:
                status, resp = hit
                source = "fixture"
            elif MODE == "replay":
                status, resp, source = 501, {"error": "no recorded answer for %s %s" % (method, path)}, "unmatched"
            elif op is None:
                status, resp, source = 404, {"error": "no operation %s %s in the API" % (method, path)}, "unknown"
            else:
                status, resp = self.apply(op, params, query, body)
                source = "state"
                if status < 300 and op["kind"] in ("create", "update", "delete", "action"):
                    self.save()
            self.record({"seq": self.seq, "via": via, "method": method, "path": path, "query": query,
                         "operation": op["name"] if op else None, "body": body, "status": status,
                         "response": resp, "source": source})
            return status, resp

    def find(self, coll, item_id):
        for i, item in enumerate(self.db.get(coll, [])):
            if isinstance(item, dict) and str(item.get("id")) == str(item_id):
                return i, item
        return -1, None

    def apply(self, op, params, query, body):
        kind, coll = op["kind"], op.get("collection")
        parent = op.get("parent") or {}
        pfield, pval = parent.get("field"), params.get(parent.get("param") or "", None)
        idp = op.get("id_param")
        if kind == "list":
            items = [x for x in self.db.get(coll, []) if isinstance(x, dict)]
            if pfield and pval is not None:
                items = [x for x in items if str(x.get(pfield)) == str(pval)]
            for k, v in (query or {}).items():
                items = [x for x in items if k not in x or str(x.get(k)) == str(v)]
            return 200, items
        if kind == "create":
            if not isinstance(body, dict):
                return 400, {"error": "the body must be a JSON object"}
            item = dict(body)
            if pfield and pval is not None:
                item[pfield] = pval
            if "id" not in item:
                item["id"] = "%s-%d" % (coll[:3].upper() or "ID", len(self.db.get(coll, [])) + 1001)
            if self.find(coll, item["id"])[1] is not None:
                return 409, {"error": "%s %s already exists" % (coll, item["id"])}
            self.db.setdefault(coll, []).append(item)
            return 201, item
        if kind in ("get", "update", "delete"):
            i, item = self.find(coll, params.get(idp))
            if item is None or (pfield and pval is not None and str(item.get(pfield)) != str(pval)):
                return 404, {"error": "%s %s not found" % (coll, params.get(idp))}
            if kind == "get":
                return 200, item
            if kind == "delete":
                del self.db[coll][i]
                return 200, {"deleted": item.get("id")}
            if not isinstance(body, dict):
                return 400, {"error": "the body must be a JSON object"}
            item.update({k: v for k, v in body.items() if k != "id"})
            return 200, item
        entry = {"operation": op["name"], "params": params, "query": query, "body": body}
        self.db["_actions"].append(entry)
        return 200, {"ok": True, "operation": op["name"]}

    def tools(self):
        out = []
        for op in self.ops:
            props, required = {}, []
            for p in op.get("path_params") or []:
                props[p] = {"type": "string", "description": "path parameter"}
                required.append(p)
            for p in op.get("query_params") or []:
                props[p] = {"type": "string", "description": "query parameter"}
            if op.get("body"):
                props["body"] = op.get("body_schema") or {"type": "object"}
                if op.get("body_required"):
                    required.append("body")
            out.append({"name": op["name"], "description": (op.get("description") or "%s %s" % (op["method"], op["path"]))[:1000],
                        "inputSchema": {"type": "object", "properties": props, "required": required}})
        return out

    def call_tool(self, name, args):
        op = next((o for o in self.ops if o["name"] == name), None)
        if op is None:
            return None
        args = args if isinstance(args, dict) else {}
        path = op["path"]
        for p in op.get("path_params") or []:
            path = path.replace("{%s}" % p, urllib.parse.quote(str(args.get(p, "")), safe=""))
        query = {p: str(args[p]) for p in op.get("query_params") or [] if p in args}
        body = args.get("body")
        if body is None and op.get("body"):
            known = set(op.get("path_params") or []) | set(op.get("query_params") or [])
            body = {k: v for k, v in args.items() if k not in known}
        return self.handle(op["method"], urllib.parse.unquote(path), query, body, "mcp")


def rpc_error(msg_id, code, message):
    return {"jsonrpc": "2.0", "id": msg_id, "error": {"code": code, "message": message}}


def rpc_result(msg_id, result):
    return {"jsonrpc": "2.0", "id": msg_id, "result": result}


def handle_message(mock, msg):
    if not isinstance(msg, dict) or msg.get("jsonrpc") != "2.0":
        return rpc_error(None, -32600, "invalid request")
    method, msg_id = msg.get("method"), msg.get("id")
    if method is None or "id" not in msg:
        return None
    params = msg.get("params") or {}
    if method == "initialize":
        asked = params.get("protocolVersion")
        return rpc_result(msg_id, {"protocolVersion": asked if asked in PROTOCOL_VERSIONS else PROTOCOL_VERSIONS[0],
                                   "capabilities": {"tools": {"listChanged": False}},
                                   "serverInfo": {"name": mock.name, "version": "1.0.0"}})
    if method == "ping":
        return rpc_result(msg_id, {})
    if method == "tools/list":
        return rpc_result(msg_id, {"tools": mock.tools()})
    if method == "tools/call":
        answer = mock.call_tool(params.get("name"), params.get("arguments") or {})
        if answer is None:
            return rpc_error(msg_id, -32602, "unknown tool: %s" % params.get("name"))
        status, resp = answer
        return rpc_result(msg_id, {"content": [{"type": "text", "text": json.dumps(resp)}], "isError": status >= 400})
    return rpc_error(msg_id, -32601, "method not found: %s" % method)


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def send_json(self, status, body, headers=None):
        data = json.dumps(body).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        for k, v in (headers or {}).items():
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(data)

    def body(self):
        length = int(self.headers.get("Content-Length") or 0)
        if length <= 0:
            return None
        if length > MAX_BODY:
            raise ValueError("body over 1 MiB")
        return json.loads(self.rfile.read(length))

    def dispatch(self, method):
        url = urllib.parse.urlsplit(self.path)
        path = urllib.parse.unquote(url.path)
        mock = self.server.mock
        if method == "GET" and path == "/healthz":
            self.send_json(200, {"ok": True, "server": mock.name})
            return
        try:
            body = self.body()
        except ValueError as e:
            self.send_json(400, {"error": str(e)})
            return
        if path == MCP_PATH:
            if method == "DELETE":
                self.send_json(200, {})
                return
            if method != "POST":
                self.send_json(405, {"error": "POST JSON-RPC here"})
                return
            batch = isinstance(body, list)
            msgs = body if batch else [body]
            answers = [a for a in (handle_message(mock, m) for m in msgs) if a is not None]
            headers = {}
            if any(isinstance(m, dict) and m.get("method") == "initialize" for m in msgs):
                headers["Mcp-Session-Id"] = uuid.uuid4().hex
            if not answers:
                self.send_response(202)
                self.send_header("Content-Length", "0")
                for k, v in headers.items():
                    self.send_header(k, v)
                self.end_headers()
            else:
                self.send_json(200, answers if batch else answers[0], headers)
            return
        query = dict(urllib.parse.parse_qsl(url.query))
        status, resp = mock.handle(method, path, query, body, "http")
        self.send_json(status, resp)

    def do_GET(self):
        self.dispatch("GET")

    def do_POST(self):
        self.dispatch("POST")

    def do_PUT(self):
        self.dispatch("PUT")

    def do_PATCH(self):
        self.dispatch("PATCH")

    def do_DELETE(self):
        self.dispatch("DELETE")

    def log_message(self, fmt, *args):
        sys.stderr.write("%s %s\n" % (self.address_string(), fmt % args))


def serve():
    httpd = ThreadingHTTPServer(("0.0.0.0", PORT), Handler)
    httpd.mock = Mock()
    sys.stderr.write("%s mock on :%d (%d operations, %d fixtures, mode %s)\n" % (httpd.mock.name, PORT, len(httpd.mock.ops), len(httpd.mock.fixtures), MODE))
    httpd.serve_forever()


def ready():
    try:
        with urllib.request.urlopen("http://127.0.0.1:%d/healthz" % PORT, timeout=2) as r:
            return 0 if r.status == 200 else 1
    except OSError:
        return 1


if __name__ == "__main__":
    if sys.argv[1:] == ["ready"]:
        sys.exit(ready())
    serve()
